1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Household identity shared by the create-owner steps. A household is the set of owners with the same
12	 * last name (compared case-insensitively with collapsed whitespace) and the same normalized address
13	 * (see {@link AddressNormalizer}). Used by {@link EnsureUniqueHousehold} to reject an un-opted-in
14	 * duplicate and by {@link AssignHousehold} to give members a single shared {@code householdId}.
15	 */
16	final class Household {
17	
18	    private Household() {
19	    }
20	
21	    /** Case-insensitive form with leading/trailing and repeated inner whitespace collapsed to one space. */
22	    static String canonical(String value) {
23	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
24	    }
25	
26	    /** Whether {@code owner} belongs to the household identified by the given last name and address. */
27	    static boolean matches(Owner owner, String lastName, String address) {
28	        return canonical(owner.getLastName()).equals(canonical(lastName))
29	                && AddressNormalizer.normalize(owner.getAddress()).equals(AddressNormalizer.normalize(address));
30	    }
31	
